(function(){
 'use strict';
 window.WBTopicUI=function(ctx){const {M,esc:e,icon,badge,heading,modal,toast}=ctx;let editing=null;const names=M.platformNames;
  function field(label,name,value,rows=3){return `<label class="form-field">${label}<textarea name="${name}" rows="${rows}" maxlength="5000">${e(value||'')}</textarea></label>`;}
  const sourceNames={work:'作品与素材',idea:'想法',news:'公开资讯',trial:'工具试用',ai:'AI 文字结果',manual:'手动新建',reference:'参考资料',benchmark:'对标分析',research:'主题研究'};
  function linkedResults(topic){const tasks=ctx.getState().tasks.filter(t=>t.sourceType==='topic'&&t.sourceId===topic.id);return tasks.length?`<section class="topic-linked-results"><h3>关联任务与结果</h3>${tasks.map(t=>`<article><div><strong>${e(t.title)}</strong><span>${t.doneAt!=null?'已勾选完成':'待行动'} · ${e(t.verificationStatus||'待验证')}</span></div>${t.resultNote?`<p class="pre-wrap">${e(t.resultNote)}</p>`:'<p>还没有补充实际结果。</p>'}${t.resultEvidence?`<p class="pre-wrap">证据：${e(t.resultEvidence)}</p>`:''}</article>`).join('')}</section>`:'';}
  function editor(value){
    editing=value;
    const referenceURL=(()=>{try{const u=new URL(value.source?.url);return ['http:','https:'].includes(u.protocol)&&!u.username&&!u.password?u.href:'';}catch{return '';}})();
    const practiceFilled=['steps','result','check','resultEvidence'].some(k=>value[k]),published=names.some(n=>value.platforms?.[n]?.status!=='未做'&&value.platforms?.[n]?.status);
    modal(value.id?'编辑选题卡':'做成一张选题卡',`<p class="topic-source">来源：${e(sourceNames[value.source?.type]||'手动新建')}${value.source?.label?' · '+e(value.source.label):''}</p>${['reference','benchmark','research'].includes(value.source?.type)&&value.source?.id?`<button class="text-button" type="button" data-action="growth-open" data-kind="${e(value.source.type)}" data-id="${e(value.source.id)}">查看本机来源</button>`:''}${referenceURL?`<a class="source-link" href="${e(referenceURL)}" target="_blank" rel="noopener noreferrer">打开原始参考</a>`:''}<form id="topic-form"><input type="hidden" name="topicId" value="${e(value.id||'')}">
      <label class="form-field">选题标题<input name="title" required maxlength="160" value="${e(value.title||'')}" placeholder="这条内容要讲清楚什么？"></label>
      <label class="form-field">写给谁？<input name="audience" maxlength="1000" value="${e(value.audience||'')}" placeholder="例如：正在尝试 AI 工作流的同行"></label>
      ${field('受众问题：解决什么真实问题？','problem',value.problem,2)}
      ${field('下一步：先做哪个小行动？','nextAction',value.nextAction,2)}
      <p class="quiet-note">先保存这几项即可。实践、发布和反馈可以之后再补。</p>
      <details class="topic-stage"><summary><span>实践与验收</span><small>${practiceFilled?'已有填写':'按需补充'}</small></summary><div class="topic-stage-body">
        <label class="form-field">当前状态<select name="status">${['候选','制作中','已发','沉淀'].map(s=>`<option ${s===value.status?'selected':''}>${s}</option>`).join('')}</select></label>
        ${field('操作步骤：具体怎样做？','steps',value.steps)}${field('实际结果：留下了什么？','result',value.result)}${field('验收标准：什么说明完成？','check',value.check)}${field('结果证据：文件位置、公开链接或观察记录','resultEvidence',value.resultEvidence)}
        <label class="form-field">核对状态<select name="verificationStatus">${['待验证','人工确认','未通过'].map(s=>`<option ${s===(value.verificationStatus||'待验证')?'selected':''}>${s}</option>`).join('')}</select></label><p class="quiet-note">“已填”只表示留下文字。人工确认表示你已核对结果与证据，勾选任务不会自动变成已实测。</p>${linkedResults(value)}
      </div></details>
      <details class="topic-stage"><summary><span>三平台发布记录</span><small>${published?'已有记录':'按需补充'}</small></summary><div class="topic-stage-body"><div class="topic-platform-editor">${names.map(name=>{const p=value.platforms?.[name]||{};return `<fieldset><legend>${name}</legend><label class="form-field">平台状态<select name="status-${name}">${['未做','草稿','已发'].map(s=>`<option ${p.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="form-field">链接<input type="url" name="url-${name}" value="${e(p.url||'')}" placeholder="https://"></label><label class="form-field">发布日期<input type="date" name="date-${name}" value="${e(p.date||'')}"></label></fieldset>`;}).join('')}</div><p class="quiet-note">两天一发是整体节奏。标记已发时请填写真实发布日期；日期未填不会计入本周发布数。</p></div></details>
      <details class="topic-stage"><summary><span>反馈与沉淀</span><small>${value.feedback?'已有填写':'按需补充'}</small></summary><div class="topic-stage-body">${field('反馈：下一次怎样调整？','feedback',value.feedback)}</div></details>
      <div class="dialog-actions">${value.id?`<button class="text-button" type="button" data-action="topic-delete" data-id="${e(value.id)}">删除此卡</button>`:''}<button class="outline-button" type="button" data-action="close">取消</button><button class="primary-button" type="submit">保存选题卡</button></div></form>`,'内容主记录');
  }
  function create(input={}){editor({...input,id:'',title:input.title||'',source:input.source||{type:'manual',id:'',label:'手动新建'},status:input.status||'候选'});}
  function edit(id){const topic=ctx.getState().topics.find(t=>t.id===id);if(topic)editor({...topic});}
  function card(t,platform){const p=platform?t.platforms[platform]:null;return `<article class="topic-card"><div class="topic-card-meta">${badge(p?p.status:t.status,p?.status==='已发'?'teal':'blue')}<span>${e(sourceNames[t.source.type]||'手动新建')}${t.source.label?' · '+e(t.source.label):''}</span></div><button class="topic-title" data-action="topic-edit" data-id="${e(t.id)}">${e(t.title)}${icon('arrow-up-right')}</button><p>${e(t.problem||'先写清楚：这条内容解决什么问题？')}</p>${t.audience?`<p class="topic-audience">写给：${e(t.audience)}</p>`:''}<p class="topic-next">下一步：${e(M.topicStep(t))}</p><div class="topic-progress">${[['problem','问题'],['steps','操作'],['result','结果'],['check','验收']].map(([key,label])=>`<span class="${t[key]?'filled':''}">${label}${t[key]?' · 已填':''}</span>`).join('')}</div><p class="topic-verification">结果核对：${e(t.verificationStatus||'待验证')}${t.resultEvidence?' · 已留证据':''}</p>${p?`<p class="topic-published">${p.date?e(p.date)+' · ':''}${p.url?`<a href="${e(p.url)}" target="_blank" rel="noopener noreferrer">打开链接 ${icon('external-link')}</a>`:'尚未填写平台链接'}</p>`:`<div class="topic-platform-badges">${names.map(n=>`<span>${n} · ${e(t.platforms[n].status)}</span>`).join('')}</div>`}<div class="topic-actions"><button class="small-button" data-action="topic-edit" data-id="${e(t.id)}">编辑卡片</button><button class="text-button" data-action="topic-task" data-id="${e(t.id)}">把下一步加入今天</button></div></article>`;}
  function render(platform){const topics=ctx.getState().topics;return `${!platform&&window.WBVisuals?window.WBVisuals.topicFlow(topics):''}<div class="collection-heading"><div><h2>${platform?platform+'的内容进度':'选题卡：共用一份内容主记录'}</h2><p>${platform?platform==='小红书'?'小红书偏图文步骤，分别准备标题、图片与说明。':'抖音和视频号偏录屏口播；具体是否出镜、配音由内容决定。':'问题 → 操作 → 结果 → 验收，三个平台各自记录状态和链接。'}</p><p class="small-caption">两天一发是整体节奏，不要求每个平台都两天一发。</p></div><button class="primary-button" data-action="topic-new">${icon('plus')}新建选题卡</button></div>${topics.length?`<div class="topic-grid">${topics.map(t=>card(t,platform)).join('')}</div>`:`<div class="empty-inline">还没有选题卡。可以从作品、想法、资讯、工具试用或AI文字结果做成一张。</div>`}`;}
  function content(data){const p=data.platform;return `${data.tabs(['共用内容库',...names],p,'real-platform')}${p==='共用内容库'?`${data.tabs(['选题卡','作品与素材','IP 主线'],data.tab,'content-tab')}${data.tab==='选题卡'?render():data.tab==='作品与素材'?`<div class="collection-heading"><div><h2>${data.works.length} 个真实作品家族</h2><p>原件、版本与发布事实分别核对，可选择一个作品做成选题。</p></div></div><div class="works-grid">${data.works.map(data.workCard).join('')}</div>`:data.ipContent()}`:render(p)}`;}
  function board(data){return `<div class="board-toolbar"><p>想法可以关联选题，明确以后再投入时间；原始资料保持原位。</p><button class="primary-button" data-action="new-idea">${icon('plus')}新增想法</button></div><div class="idea-cards">${data.ideas.map(data.ideaCard).join('')}${ctx.getState().ideas.map(i=>`<article class="idea-real user-idea">${badge(i.lane||'我的想法','teal')}<h3>${e(i.title)}</h3><p>${e(i.body)}</p><span class="record-foot">我的本地记录</span><div class="user-idea-actions"><button class="small-button" data-action="topic-from-idea" data-user="true" data-id="${e(i.id)}">转成选题</button><button class="text-button" data-action="user-idea-delete" data-id="${e(i.id)}">删除想法</button></div></article>`).join('')}</div>`;}
  function handle(action,el){const id=el.dataset.id;if(action==='topic-new'){create();return true;}if(action==='topic-edit'){edit(id);return true;}if(action==='topic-task'){const t=ctx.getState().topics.find(t=>t.id===id);if(t){const step=M.topicStep(t);M.addTask(ctx.getState(),'推进选题：'+t.title+' · '+step,20,{body:'下一步补充：'+step+'。\n'+(t.problem||''),evidence:t.check||'在选题卡里留下可核对的结果',sourceType:'topic',sourceId:t.id,dedupe:true});ctx.save();toast('已把选题下一步加入今天');ctx.render();}return true;}if(action==='topic-delete'){modal('删除这张选题卡？',`<p>只删除这张本机卡片，不修改来源作品或发布平台。</p><div class="dialog-actions"><button class="outline-button" data-action="close">保留</button><button class="primary-button" data-action="topic-delete-confirm" data-id="${e(id)}">确认删除</button></div>`,'选题卡');return true;}if(action==='topic-delete-confirm'){M.deleteTopic(ctx.getState(),id);ctx.save();document.querySelector('#dialog').close();ctx.render();toast('选题卡已删除');return true;}return false;}
  function submit(form){if(form.getAttribute('id')!=='topic-form')return false;const f=new FormData(form),input={title:String(f.get('title')||'').trim(),status:String(f.get('status')),source:editing?.source||{type:'manual',id:'',label:'手动新建'},platforms:{}};for(const k of ['audience','problem','nextAction','steps','result','check','resultEvidence','verificationStatus','feedback'])input[k]=String(f.get(k)||'');for(const n of names)input.platforms[n]={status:String(f.get('status-'+n)),url:String(f.get('url-'+n)||''),date:String(f.get('date-'+n)||'')};if(!input.title){toast('请先写选题标题');return true;}const id=String(f.get('topicId')||'');if(id)M.updateTopic(ctx.getState(),id,input);else M.addTopic(ctx.getState(),input);ctx.save();document.querySelector('#dialog').close();ctx.render();toast('选题卡已保存');return true;}
  return {render,content,board,create,edit,handle,submit};
 };
})();
